import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_PLAZA, MODELO_URBANIZACION, TABLA_PLAZAS } from '../../models/urbanizacion-plaza.model.mjs';

export async function crearPlazaRepository(plaza) {
  await MODELO_PLAZA.build(PutItemCommand)
    .item(plaza)
    .options({ condition: { attr: 'plazaId', exists: false } })
    .send();
}

export async function listarPlazasRepository() {
  const { Items = [] } = await TABLA_PLAZAS.build(ScanCommand)
    .entities(MODELO_PLAZA)
    .options({ consistent: true })
    .send();
  return Items;
}

