import { MODELO_PLAZA, MODELO_URBANIZACION, TABLA_PLAZAS } from '../../models/urbanizacion-plaza.model.mjs';

export async function buscarUrbanizacionRepository(urbanizacionId) {
  const { Item } = await MODELO_URBANIZACION.build(GetItemCommand)
    .key({ urbanizacionId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarUrbanizacionRepository(urbanizacionId, minimo) {
  const { Items = [] } = await TABLA_PLAZAS.build(QueryCommand)
    .entities(MODELO_PLAZA)
    .query({ index: 'PorUrbanizacion', partition: urbanizacionId })
    .options({ filters: { Plaza: { attr: 'superficieM2', gte: minimo } } })
    .send();
  return Items;
}

import { trasladarPlazaService } from './service.mjs';

export async function handler(event) {
  const plazaId = Number(event.pathParameters.plazaId);
  const { urbanizacionId } = JSON.parse(event.body);
  const resultado = await trasladarPlazaService(plazaId, urbanizacionId);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { trasladarPlazaRepository } from './repository.mjs';
import { buscarUrbanizacionRepository } from '../../urbanizaciones/consultar/repository.mjs';

export async function trasladarPlazaService(plazaId, urbanizacionId) {
  const urbanizacion = await buscarUrbanizacionRepository(urbanizacionId);
  if (!urbanizacion) throw new Error('Urbanizacion no encontrado');
  return trasladarPlazaRepository(plazaId, urbanizacionId);
}

import { UpdateItemCommand } from 'dynamodb-toolbox/entity/actions/update';
import { MODELO_PLAZA, MODELO_URBANIZACION, TABLA_PLAZAS } from '../../models/urbanizacion-plaza.model.mjs';

export async function trasladarPlazaRepository(plazaId, urbanizacionId) {
  const { Attributes } = await MODELO_PLAZA.build(UpdateItemCommand)
    .item({ plazaId, urbanizacionId })
    .options({
      condition: { attr: 'plazaId', exists: true },
      returnValues: 'ALL_NEW'
    })
    .send();
  return Attributes;
}

import { consultarUrbanizacionService } from './service.mjs';

export async function handler(event) {
  const urbanizacionId = Number(event.pathParameters.urbanizacionId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarUrbanizacionService(urbanizacionId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarUrbanizacionRepository, consultarUrbanizacionRepository } from './repository.mjs';

export async function consultarUrbanizacionService(urbanizacionId, minimo) {
  const urbanizacion = await buscarUrbanizacionRepository(urbanizacionId);
  if (!urbanizacion) throw new Error('Urbanizacion no encontrado');
  const plazas = await consultarUrbanizacionRepository(urbanizacionId, minimo);
  return { urbanizacion, plazas };
}

